<style>
:root{--forest:#294f40;--green:#47745d;--sage:#e6eee6;--cream:#f7f5ed;--ink:#29362f;--muted:#7b877f;--line:#e8e9e1}
*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font-family:"Segoe UI",Arial,sans-serif}
.admin-wrapper{min-height:100vh}.sidebar{width:255px;position:fixed;inset:0 auto 0 0;z-index:1030;background:var(--forest);color:white;padding:24px 18px;display:flex;flex-direction:column}
.brand{display:flex;align-items:center;gap:12px;padding:5px 10px 30px;color:white;text-decoration:none}.brand-mark{width:42px;height:42px;border-radius:13px;display:grid;place-items:center;background:#e6ecdf;color:var(--forest);font-size:21px}.brand-name{font-weight:700;font-size:18px}.brand-sub{display:block;color:#c3d2c8;font-size:11px;font-weight:400}
.menu-label{color:#a9c0b2;font-size:10px;font-weight:700;letter-spacing:1.3px;padding:12px}.sidebar .nav-link{color:#d8e3dc;padding:11px 13px;border-radius:10px;display:flex;gap:12px;align-items:center;font-size:13px;margin:3px 0}.sidebar .nav-link i{font-size:17px;width:20px}.sidebar .nav-link:hover,.sidebar .nav-link.active{color:var(--forest);background:#edf1e8}
.sidebar-bottom{margin-top:auto;border-top:1px solid #ffffff26;padding-top:15px}.main-area{margin-left:255px;min-height:100vh;display:flex;flex-direction:column}
.topbar{height:72px;background:white;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 30px}.topbar-title{font-weight:650;font-size:15px}.admin-chip{display:flex;align-items:center;gap:10px;font-size:13px}.avatar{width:36px;height:36px;border-radius:50%;display:grid;place-items:center;background:var(--sage);color:var(--forest)}
.page-content{padding:30px;flex:1}.page-heading{display:flex;justify-content:space-between;gap:15px;margin-bottom:24px}.page-heading h1{font-size:25px;font-weight:700;margin:0 0 6px;color:var(--forest)}.page-heading p{margin:0;color:var(--muted);font-size:13px}
.stat-card,.content-card{background:white;border:1px solid var(--line);border-radius:15px;box-shadow:0 3px 14px #26423209}.stat-card{padding:20px;height:100%}.stat-icon{width:43px;height:43px;display:grid;place-items:center;border-radius:12px;font-size:19px;background:var(--sage);color:var(--green)}.stat-label{color:var(--muted);font-size:12px;margin-top:16px}.stat-value{color:var(--forest);font-size:27px;font-weight:700;margin-top:3px}
.card-heading{padding:18px 21px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}.card-heading h2{font-size:15px;font-weight:700;margin:0;color:var(--forest)}.table{margin:0;font-size:13px;vertical-align:middle}.table thead th{color:#78857c;font-size:11px;text-transform:uppercase;background:#fafbf8;border-bottom:1px solid var(--line);padding:13px 16px;white-space:nowrap}.table tbody td{padding:14px 16px;border-color:#f0f1ec}
.badge-soft{background:var(--sage);color:var(--green);font-weight:600}.btn-green{background:var(--green);color:white;border:0;border-radius:9px}.btn-green:hover{background:var(--forest);color:white}.btn-outline-green{color:var(--green);border:1px solid #b9cbbd;border-radius:8px;font-size:12px}.btn-outline-green:hover{background:var(--sage);color:var(--forest)}
.site-footer{padding:16px 30px;color:var(--muted);font-size:11px;border-top:1px solid var(--line);background:white}
@media(max-width:991.98px){.sidebar{transform:translateX(-100%);transition:.25s}.sidebar.show{transform:translateX(0)}.main-area{margin-left:0}.topbar{padding:0 18px}.page-content{padding:22px 18px}}
</style>
